{
  "model": "claude-sonnet-5",
  "max_tokens": 500,
  "tools": [{
    "name": "classify_maintenance_request",
    "description": "Classify a property maintenance request",
    "input_schema": {
      "type": "object",
      "properties": {
        "urgency": {"type": "string", "enum": ["Emergency", "Urgent", "Routine"]},
        "category": {"type": "string", "enum": ["Plumbing", "Electrical", "HVAC", "Appliance", "Structural", "Pest", "General", "Other"]},
        "summary": {"type": "string"},
        "confidence": {"type": "number"},
        "needs_human_review": {"type": "boolean"}
      },
      "required": ["urgency", "category", "summary", "confidence", "needs_human_review"]
    }
  }],
  "tool_choice": {"type": "tool", "name": "classify_maintenance_request"},
  "system": "You are a property maintenance triage assistant. Classify urgency (Emergency = safety/habitability risk like no heat, gas smell, flooding, no working toilet; Urgent = needs attention within days; Routine = everything else), category, and write a one-sentence summary. Set needs_human_review true for any Emergency, or if confidence is below 0.7.",
  "messages": [{
    "role": "user",
  "content": "Tenant:{{2.`Tenant Name`}}\nUnit:{{2.`Unit Number`}}\nRequest: {{2.Description}}"
  }]
}

